function gotCount(member, boss, item) {
  const counts = BOARD.clog[member.id] && BOARD.clog[member.id][boss.slug];
  if (!counts || counts[item.id] == null) return null;
  return counts[item.id];
}
function nextCycleId(member, boss) {
  const pieces = boss.uniques.filter(function (item) { return item.cycle != null; }).sort(function (a, b) { return a.cycle - b.cycle; });
  if (!pieces.length) return null;
  const counts = pieces.map(function (item) { return gotCount(member, boss, item); });
  if (counts.some(function (n) { return n == null; })) return null;
  const low = Math.min.apply(null, counts);
  const next = pieces.find(function (item) { return gotCount(member, boss, item) === low; });
  return next ? next.id : null;
}
function oneKill(member, boss, item) {
  if (item.delveRates) {
    const levels = Object.keys(item.delveRates).map(Number).filter(function (level) { return delveAt(member.id, level) > 0; });
    if (!levels.length) return null;
    const level = Math.max.apply(null, levels);
    return { p: 1 / item.delveRates[level], place: "level " + (level >= 9 ? "9+" : level), kc: delveTotal(member.id) };
  }
  if (item.sources) {
    let best = null;
    item.sources.forEach(function (src) {
      const kc = partKc(member, boss, src.part);
      if (kc <= 0) return;
      const p = src.num / src.den;
      if (!best || p > best.p) {
        const part = (boss.parts || []).find(function (row) { return row.id === src.part; });
        best = { p: p, place: part ? part.name : src.part, kc: kc };
      }
    });
    return best;
  }
  const kc = item.part ? partKc(member, boss, item.part) : kcFor(member, boss).kc;
  if (kc <= 0 || !item.rate) return null;
  const part = item.part && (boss.parts || []).find(function (row) { return row.id === item.part; });
  return { p: 1 / item.rate, place: part ? part.name : boss.name, kc: kc };
}
function nextDrops(member) {
  if (!BOARD.clog[member.id]) return [];
  const ranked = [];
  const seen = {};
  BOARD.bosses.forEach(function (boss) {
    const cycleId = nextCycleId(member, boss);
    boss.uniques.forEach(function (item) {
      const got = gotCount(member, boss, item);
      if (got == null) return;
      const cyclePiece = item.cycle != null;
      if (cyclePiece && item.id !== cycleId) return;
      if (!cyclePiece && got > 0) return;
      const chance = oneKill(member, boss, item);
      if (!chance) return;
      const key = item.name.toLowerCase();
      const row = { boss: boss, item: item, got: got, chance: chance, cyclePiece: cyclePiece };
      if (!seen[key] || chance.p > seen[key].chance.p) seen[key] = row;
    });
  });
  Object.keys(seen).forEach(function (key) { ranked.push(seen[key]); });
  ranked.sort(function (a, b) { return b.chance.p - a.chance.p; });
  return ranked.slice(0, 8);
}
function renderNext() {
  const main = document.getElementById("main");
  main.innerHTML = "";
  main.appendChild(el("div", "label", "Group"));
  main.appendChild(el("h1", "", "Next drops"));
  main.appendChild(el("p", "note", "Missing collection log items, ranked by the chance on one more kill. Being dry does not make the next kill luckier. Hydra and Araxxor only list the piece the cycle can roll."));
  BOARD.members.forEach(function (member) {
    const block = el("section", "who-block");
    block.appendChild(el("h2", "", member.rsn));
    const rows = nextDrops(member);
    if (!BOARD.clog[member.id]) {
      block.appendChild(el("p", "note", "No DropTracker collection log yet, so this would be a guess."));
      main.appendChild(block);
      return;
    }
    if (!rows.length) {
      block.appendChild(el("p", "note", "Nothing to rank. Either the log is finished where there is kill count, or the KC is still missing."));
      main.appendChild(block);
      return;
    }
    rows.forEach(function (row, index) {
      const link = document.createElement("a");
      link.className = "next-row";
      link.href = bossHref(row.boss.slug);
      const rate = Math.max(1, Math.round(1 / row.chance.p));
      const title = el("div", "name");
      title.append((index + 1) + ". " + row.item.name);
      if (row.cyclePiece) title.append(el("span", "tag ok", "Next piece"));
      link.appendChild(title);
      const where = row.chance.place === row.boss.name ? "" : row.chance.place + " · ";
      link.appendChild(el("div", "sub", row.boss.name + " · " + where + num(row.chance.kc) + " kc · 1/" + num(rate) + (row.got ? " · already " + row.got : "")));
      block.appendChild(link);
    });
    main.appendChild(block);
  });
}
function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text != null) node.textContent = text;
  return node;
}

function renderNav() {
  const regionBox = document.getElementById("regions");
  const list = document.getElementById("bosses");
  const pick = document.getElementById("pick");
  const aside = document.querySelector("aside");
  let kinds = document.getElementById("kinds");
  if (!kinds && aside) {
    kinds = el("div", "regions");
    kinds.id = "kinds";
    aside.insertBefore(kinds, aside.firstChild);
  }
  let who = document.getElementById("who");
  if (!who && aside) {
    who = el("div", "who");
    who.id = "who";
    aside.insertBefore(who, aside.firstChild);
  }
  if (who) {
    who.innerHTML = "";
    who.appendChild(el("div", "label", "Player"));
    const playerPick = document.createElement("select");
    playerPick.className = "menu-select";
    BOARD.members.forEach(function (m) {
      const option = el("option", "", m.rsn);
      option.value = m.id;
      if (m.id === memberId) option.selected = true;
      playerPick.appendChild(option);
    });
    playerPick.onchange = function () { memberId = playerPick.value; renderMain(); };
    who.appendChild(playerPick);
  }
  if (kinds) {
    kinds.innerHTML = "";
    [["boss", "Bosses"], ["monster", "Monsters"]].forEach(function (pair) {
      const button = el("button", pair[0] === section ? "on" : "", pair[1]);
      button.type = "button";
      button.onclick = function () {
        section = pair[0];
        region = "All";
        const first = BOARD.bosses.find(function (b) { return (b.kind || "boss") === section; });
        if (first) goBoss(first.slug);
        else renderNav();
      };
      kinds.appendChild(button);
    });
    const nextButton = el("button", isNext() ? "on" : "", "Next drops");
    nextButton.type = "button";
    nextButton.onclick = goNext;
    kinds.appendChild(nextButton);
  }
  const label = aside && aside.querySelector(".label");
  if (label) label.textContent = section === "monster" ? "Monsters" : "Bosses";
  regionBox.innerHTML = "";
  list.innerHTML = "";
  if (pick) pick.innerHTML = "";
  const active = isNext() ? "" : currentBoss().slug;
  const pool = BOARD.bosses.filter(function (b) { return (b.kind || "boss") === section; });
  const regions = ["All"].concat(pool.map(function (b) { return b.region; }).filter(function (v, i, a) { return a.indexOf(v) === i; }));
  regionBox.appendChild(el("div", "label", "Category"));
  const regionPick = document.createElement("select");
  regionPick.className = "menu-select";
  regions.forEach(function (name) {
    const option = el("option", "", name);
    option.value = name;
    if (name === region) option.selected = true;
    regionPick.appendChild(option);
  });
  regionPick.onchange = function () {
    const name = regionPick.value;
    region = name;
    const first = pool.find(function (b) { return name === "All" || b.region === name; });
    if (first) goBoss(first.slug);
    else renderNav();
  };
  regionBox.appendChild(regionPick);
  pool.filter((b) => region === "All" || b.region === region).forEach((boss) => {
    const button = el("button", boss.slug === active ? "on" : "", boss.name);
    button.type = "button";
    button.onclick = () => { goBoss(boss.slug); };
    list.appendChild(button);
  });
}

function medalFile(tone) {
  if (tone === "cursed" || tone === "dry" || tone === "unlucky" || tone === "lucky" || tone === "spoon") return tone;
  return "ok";
}
let soundOn = false;
let callAudio = null;
function callSlug(value) {
  return String(value || "").toLowerCase().replace(/'/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}
function playClip(src, done) {
  if (callAudio) { callAudio.onended = null; callAudio.onerror = null; callAudio.pause(); }
  const audio = new Audio(src);
  callAudio = audio;
  let finished = false;
  function finish() {
    if (finished) return;
    finished = true;
    done();
  }
  audio.onended = finish;
  audio.onerror = finish;
  const pending = audio.play();
  if (pending && pending.catch) pending.catch(finish);
}
function hideRarePopup() {
  const pop = document.getElementById("rare-pop");
  if (pop) pop.remove();
}
function showRarePopup(fill) {
  const item = fill.dataset.item || "";
  if (!/leather|claw/i.test(item)) return false;
  hideRarePopup();
  const medal = fill.closest(".meter") && fill.closest(".meter").querySelector(".medal");
  const pop = document.createElement("div");
  pop.id = "rare-pop";
  pop.className = "rare-pop";
  const card = document.createElement("div");
  card.className = "rare-card";
  if (medal) {
    const img = document.createElement("img");
    img.src = medal.src;
    img.alt = "";
    card.appendChild(img);
  }
  const title = document.createElement("div");
  title.className = "rare-title";
  title.textContent = item;
  const word = document.createElement("div");
  word.className = "tag " + (fill.dataset.tone || "");
  word.textContent = fill.dataset.word || "";
  card.append(title, word);
  pop.appendChild(card);
  pop.addEventListener("click", hideRarePopup);
  document.body.appendChild(pop);
  return true;
}
function playCall(item, word, done) {
  const base = depthPrefix() + "calls/";
  playClip(base + callSlug(item) + ".mp3", function () {
    window.setTimeout(function () {
      playClip(base + callSlug(word) + ".mp3", done);
    }, 180);
  });
}
let hydraRun = 0;
function runHydraSequence(fills) {
  const run = ++hydraRun;
  function step(index) {
    if (run !== hydraRun || index >= fills.length) return;
    const fill = fills[index];
    const medal = fill.closest(".meter") && fill.closest(".meter").querySelector(".medal");
    let moved = false;
    function goNext() {
      if (moved || run !== hydraRun) return;
      moved = true;
      step(index + 1);
    }
    fill.addEventListener("transitionend", function (event) {
      if (event.propertyName !== "width" || run !== hydraRun) return;
      if (medal) medal.classList.add("pop");
      const rare = showRarePopup(fill);
      if (soundOn) {
        playCall(fill.dataset.item, fill.dataset.word, function () { hideRarePopup(); goNext(); });
        window.setTimeout(function () { hideRarePopup(); goNext(); }, 8000);
      } else if (rare) {
        window.setTimeout(function () { hideRarePopup(); goNext(); }, 1600);
      } else {
        window.setTimeout(goNext, 280);
      }
    });
    window.setTimeout(function () {
      if (run === hydraRun) fill.style.width = fill.dataset.width;
    }, 50);
  }
  step(0);
}
function replayHydra() {
  soundOn = true;
  hideRarePopup();
  if (callAudio) { callAudio.pause(); callAudio = null; }
  const fills = Array.from(document.querySelectorAll("#main .fill.arm"));
  fills.forEach(function (fill) {
    const medal = fill.closest(".meter") && fill.closest(".meter").querySelector(".medal");
    if (medal) medal.classList.remove("pop");
    fill.style.transition = "none";
    fill.style.width = "0%";
  });
  window.requestAnimationFrame(function () {
    window.requestAnimationFrame(function () {
      fills.forEach(function (fill) { fill.style.transition = ""; });
      runHydraSequence(fills);
    });
  });
}
let hydraIntroDone = false;
function armHydraMeters(root) {
  const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const fills = Array.from(root.querySelectorAll(".fill.arm"));
  if (reduce) {
    fills.forEach(function (fill) {
      fill.style.width = fill.dataset.width;
      const medal = fill.closest(".meter") && fill.closest(".meter").querySelector(".medal");
      if (medal) medal.classList.add("pop");
    });
    return;
  }
  if (!hydraIntroDone) {
    hydraIntroDone = true;
    runHydraSequence(fills);
    return;
  }
  fills.forEach(function (fill) {
    fill.style.width = fill.dataset.width;
    const medal = fill.closest(".meter") && fill.closest(".meter").querySelector(".medal");
    if (medal) medal.classList.add("pop");
  });
}
function meterRow(label, sub, got, expected, animate) {
  const delta = got - expected;
  const verdict = roast(got, expected, label);
  const width = Math.max(8, Math.min(100, Math.abs(delta) / Math.max(expected, 1) * 100));
  const row = el("div", "meter");
  const copy = el("div");
  const name = el("div", "name");
  name.append(label, el("span", "tag " + verdict.tone, verdict.word));
  if (animate) {
    const medal = document.createElement("img");
    medal.className = "medal";
    medal.alt = "";
    medal.src = depthPrefix() + "medals/" + medalFile(verdict.tone) + ".jpg";
    name.appendChild(medal);
  }
  copy.appendChild(name);
  if (sub) copy.appendChild(el("div", "sub", sub));
  const track = el("div", "track");
  const fill = el("div", "fill " + verdict.tone + (animate ? " arm" : ""));
  fill.style.width = animate ? "0%" : width + "%";
  if (animate) {
    fill.dataset.width = width + "%";
    fill.dataset.tone = verdict.tone;
    fill.dataset.word = verdict.word;
    fill.dataset.item = label === "Any" ? "This table" : label;
  }
  const deltaEl = el("div", "delta", signed(delta));
  track.append(fill, deltaEl);
  row.append(copy, el("div", "got", String(got)), track);
  return { row, delta, expected, got, tone: verdict.tone, word: verdict.word };
}


function kcHeadingBit(member, boss, table, opts) {
  // Fold auto-updating KC into the first visible drop-table heading (or each DT part).
  opts = opts || {};
  if (boss.parts && table) {
    const part = boss.parts.find(function (p) { return p.id === table.id; });
    if (part) {
      const value = partKc(member, boss, part.id);
      return value ? " · " + num(value) + " KC" : "";
    }
    return "";
  }
  if (boss.delves) return "";
  // Normal bosses: KC on the first visible table only (Vorkath tertiary, Zulrah rare, …).
  if (table && opts.firstVisible === false) return "";
  const kc = kcFor(member, boss);
  if (!kc.kc) return "";
  return " · " + num(kc.kc) + " KC";
}

function renderMain() {
  if (isNext()) return renderNext();
  const boss = currentBoss();
  const main = document.getElementById("main");
  main.innerHTML = "";
  const member = BOARD.members.find((m) => m.id === memberId) || BOARD.members[0];
  const kc = kcFor(member, boss);
  const counts = (BOARD.clog[member.id] && BOARD.clog[member.id][boss.slug]) || null;
  if (!hasAtmTitlePlate(boss.slug)) {
    main.appendChild(el("div", "label", boss.region));
    const title = el("h1", "", boss.name);
    main.appendChild(title);
  }
  if (boss.note) main.appendChild(el("p", "note", boss.note));

  // KC lives in the Rare drop table (or part-table) heading — skip the tall KPI strip
  // except for delve bosses (deep delves vs level clears) which need both numbers.
  if (boss.delves) {
    const kpis = el("div", "kpis");
    const deep = womKc(member.id, boss.wom);
    const deepBox = el("div", "kpi");
    deepBox.append(el("span", "label", "Deep delves"), el("b", "", deep ? num(deep) : "–"), el("span", "sub", "hiscores, not the rolls"));
    const clearBox = el("div", "kpi");
    const clears = delveTotal(member.id);
    clearBox.append(el("span", "label", "Level clears"), el("b", "", clears ? num(clears) : "–"));
    kpis.append(deepBox, clearBox);
    main.appendChild(kpis);
  }

  if (!counts) {
    const bareKc = kcHeadingBit(member, boss, null);
    if (bareKc) main.appendChild(el("div", "label", "Kill count" + bareKc));
    main.appendChild(el("p", "note", boss.kind === "monster"
      ? member.rsn + " has no collection log count for this monster yet. It is not on the hiscores, so type a loot-tracker KC."
      : member.rsn + " has no DropTracker collection log yet, so luck is not scored. Kill count still comes from Wise Old Man."));
  } else if (!bossHasKc(member, boss)) {
    main.appendChild(el("p", "note", boss.delves
      ? "Hiscores are deep delves, not the loot rolls. Type how many times each level was cleared."
      : boss.kind === "monster"
      ? "Not on the hiscores. Type the loot-tracker KC and the luck bars will use it. Collection log counts are filled in."
      : "Collection log is in, but there is no kill count yet, so expected drops stay blank."));
    boss.uniques.forEach(function (item) {
      main.appendChild(el("p", "", (counts[item.id] || 0) + "  " + item.name));
    });
  } else if (boss.uniques.length) {
  const scored = boss.uniques.some(function (item) { return item.rate != null; });
  if (!scored) {
    main.appendChild(el("p", "note", "No flat unique rate — showing collection log counts with KC. Luck meters stay off."));
    const heading = el("div", "label", "Collection log" + kcHeadingBit(member, boss, null));
    heading.style.marginTop = "1.15rem";
    main.appendChild(heading);
    const list = el("div", "clog-list");
    boss.uniques.forEach(function (item) {
      const got = counts[item.id] || 0;
      const row = el("div", "clog-row" + (got ? " got" : ""));
      row.append(el("span", "clog-qty", String(got)), el("span", "clog-name", item.name));
      list.appendChild(row);
    });
    main.appendChild(list);
  } else {
  const animate = boss.slug === "alchemical-hydra";
  const tables = boss.tables || [
    { id: "rare", label: "Rare drop table" },
    { id: "mutagen", label: "Mutagens" },
    { id: "tertiary", label: "Tertiary" }
  ];
  let firstVisibleTable = true;
  tables.forEach(function (table) {
    const items = boss.uniques.filter(function (item) { return (item.table || "rare") === table.id; });
    if (!items.length) return;
    let sumGot = 0;
    let sumExpected = 0;
    const rows = [];
    items.forEach(function (item) {
      const got = counts[item.id] || 0;
      const expected = itemExpected(member, boss, item);
      sumGot += got;
      sumExpected += expected;
      rows.push(meterRow(item.name, rateText(member, boss, item, expected), got, expected, animate));
    });
    const verdict = roast(sumGot, sumExpected, table.label);
    const heading = el("div", "label table-heading");
    heading.appendChild(el("span", "heading-text", table.label));
    const kcBit = kcHeadingBit(member, boss, table, { firstVisible: firstVisibleTable });
    if (kcBit) heading.appendChild(el("span", "heading-kc", kcBit));
    const tableHasRate = items.some(function (item) { return item.rate != null; });
    if (tableHasRate) {
      heading.appendChild(el("span", "heading-separator", " · "));
      heading.appendChild(el("span", "tag " + verdict.tone, "Luck · " + verdict.word));
    }
    firstVisibleTable = false;
    heading.style.marginTop = "1.15rem";
    const head = el("div", "head");
    head.append(el("span", "", "Expected"), el("span", "", "Received"));
    main.append(heading);
    if (items.length > 1) {
      const any = meterRow("Any", "This table only", sumGot, sumExpected, animate);
      main.append(head, any.row);
    } else {
      main.append(head);
    }
    rows.forEach(function (entry) { main.appendChild(entry.row); });
  });
  if (animate) armHydraMeters(main);
  if (animate) {
    const hear = el("button", "update", "Hear the calls");
    hear.type = "button";
    hear.style.marginTop = "1rem";
    hear.onclick = replayHydra;
    main.appendChild(hear);
  }
  }
  } else {
    main.appendChild(el("p", "note", "No flat unique rate for this boss. KC only."));
  }

  if (boss.delves) {
    const form = el("p", "note");
    form.style.marginTop = "1rem";
    form.appendChild(document.createTextNode("Clears of that level. A run to 8 is one clear on every level up to 8. "));
    [1, 2, 3, 4, 5, 6, 7, 8, 9].forEach(function (level) {
      const input = document.createElement("input");
      input.type = "number";
      input.min = "0";
      input.placeholder = level === 9 ? "9+" : String(level);
      input.value = delveSaved(member.id)[level] != null && delveSaved(member.id)[level] !== "" ? delveSaved(member.id)[level] : "";
      input.style.cssText = "width:5rem;margin:0 .55rem .35rem .2rem;background:#0f141a;border:1px solid #2a3440;border-radius:.5rem;padding:.35rem .5rem";
      input.onchange = () => {
        const saved = panelStore();
        saved[member.id] = saved[member.id] || {};
        saved[member.id].delveEdits = saved[member.id].delveEdits || {};
        saved[member.id].delveEdits[level] = input.value === "" ? "" : Number(input.value);
        savePanel(saved);
        renderMain();
      };
      form.append((level === 9 ? "9+" : String(level)) + " ", input);
    });
    main.appendChild(form);
  } else if (boss.parts) {
    const form = el("p", "note");
    form.style.marginTop = "1rem";
    form.appendChild(document.createTextNode("Loot-tracker KC overrides that boss. "));
    boss.parts.forEach(function (part) {
      const input = document.createElement("input");
      input.type = "number";
      input.min = "0";
      input.placeholder = part.name;
      input.value = panelKc(member.id, part.slug) || "";
      input.style.cssText = "width:5.5rem;margin:0 .55rem .35rem .2rem;background:#0f141a;border:1px solid #2a3440;border-radius:.5rem;padding:.35rem .5rem";
      input.onchange = () => {
        const saved = panelStore();
        saved[member.id] = saved[member.id] || {};
        saved[member.id][part.slug] = input.value === "" ? "" : Number(input.value);
        savePanel(saved);
        renderMain();
      };
      form.append(part.name + " ", input);
    });
    main.appendChild(form);
  } else {
  const form = el("p", "note");
  form.style.marginTop = "1rem";
  form.textContent = boss.kind === "monster"
    ? "Not on the hiscores. Loot-tracker KC is what the luck math uses. "
    : "Loot-tracker KC overrides hiscores for the luck math. ";
  const input = document.createElement("input");
  input.type = "number";
  input.min = "0";
  input.placeholder = "Panel KC";
  input.value = panelKc(member.id, boss.slug) || "";
  input.style.cssText = "width:7rem;background:#0f141a;border:1px solid #2a3440;border-radius:.5rem;padding:.35rem .5rem";
  input.onchange = () => {
    const saved = panelStore();
    saved[member.id] = saved[member.id] || {};
    saved[member.id][boss.slug] = input.value === "" ? "" : Number(input.value);
    savePanel(saved);
    renderMain();
  };
  form.appendChild(input);
  main.appendChild(form);
  }
  if (BOARD.synced) {
    main.appendChild(el("p", "note", "Collection log synced " + String(BOARD.synced).slice(0, 16).replace("T", " ") + " UTC from " + logSource + "."));
  }
}

function render() {
  ensureUpdateButton();
  if (!isNext()) section = (currentBoss().kind === "monster") ? "monster" : "boss";
  updateAtmosphere();
  renderNav();
  renderMain();
  document.title = isNext() ? "Next drops · No mistakes" : currentBoss().name + " · No mistakes";
}

let refreshing = false;
let logSource = "RuneProfile";
function normName(value) {
  return String(value || "").toLowerCase().replace(/'/g, "").replace(/[^a-z0-9]+/g, " ").trim();
}
const CLOG_PAGES = {
  "the-corrupted-gauntlet": ["The Gauntlet"],
  "tzkal-zuk": ["The Inferno"],
  "nightmare": ["The Nightmare"],
  "phosanis-nightmare": ["The Nightmare"],
  "desert-treasure-ii": ["Duke Sucellus", "The Leviathan", "The Whisperer", "Vardorvis"],
  "demonic-gorilla": ["Glough's Experiments"],
  "tormented-demon": ["Tormented Demons"],
  "chambers-of-xeric": ["Chambers of Xeric"],
  "chambers-of-xeric-cm": ["Chambers of Xeric"],
  "theatre-of-blood": ["Theatre of Blood"],
  "theatre-of-blood-hm": ["Theatre of Blood"],
  "tombs-of-amascut": ["Tombs of Amascut"],
  "tombs-of-amascut-expert": ["Tombs of Amascut"],
  "sol-heredit": ["Fortis Colosseum"],
};
function applyRuneProfile(member, data) {
  if (!data || data.obtained == null) return false;
  const byName = {};
  (data.tabs || []).forEach(function (tab) {
    (tab.pages || []).forEach(function (page) { byName[normName(page.name)] = page; });
  });
  const next = Object.assign({}, BOARD.clog[member.id] || {});
  let wrote = 0;
  BOARD.bosses.forEach(function (boss) {
    if (!boss.uniques.length) return;
    const names = CLOG_PAGES[boss.slug] || (byName[normName(boss.name)] ? [boss.name] : (byName.slayer ? ["Slayer", "Miscellaneous"] : [boss.name]));
    const row = {};
    let hits = 0;
    boss.uniques.forEach(function (item) {
      const wanted = normName(item.name);
      let found = null;
      names.forEach(function (name) {
        const page = byName[normName(name)];
        if (!page || found != null) return;
        (page.items || []).forEach(function (slot) {
          if (found == null && normName(slot.name) === wanted) found = Number(slot.quantity) || 0;
        });
      });
      if (found != null) {
        row[item.id] = found;
        hits++;
      }
    });
    // Accept a page when every unique matched, or when most of a large raid log matched.
    if (hits === boss.uniques.length || (boss.uniques.length >= 8 && hits >= Math.ceil(boss.uniques.length * 0.7))) {
      // Fill gaps with 0 so UI keys stay stable.
      boss.uniques.forEach(function (item) {
        if (row[item.id] == null) row[item.id] = 0;
      });
      next[boss.slug] = row;
      wrote++;
    }
  });
  if (!wrote) return false;
  BOARD.clog[member.id] = next;
  return true;
}
async function refreshLogs() {
  const names = [];
  for (const member of BOARD.members) {
    try {
      const response = await fetch("https://api.runeprofile.com/v1/accounts/" + encodeURIComponent(member.rsn) + "/collection-log", { headers: { Accept: "application/json" } });
      if (!response.ok) continue;
      const data = await response.json();
      if (applyRuneProfile(member, data)) names.push(member.rsn);
    } catch (e) {}
  }
  if (names.length) {
    logSource = "RuneProfile";
    BOARD.synced = new Date().toISOString().slice(0, 19);
  }
  return names;
}
function applySnapshot(member, data) {
  const bosses = (data.latestSnapshot && data.latestSnapshot.data && data.latestSnapshot.data.bosses) || {};
  liveKc[member.id] = {};
  liveUpdated[member.id] = data.updatedAt || "";
  Object.keys(bosses).forEach(function (key) {
    const kills = bosses[key] && bosses[key].kills;
    if (kills > 0) liveKc[member.id][key] = kills;
  });
}
function ensureUpdateButton() {
  // Prefer Update/status below the boss list so Imagine title plates stay clear.
  let button = document.getElementById("update");
  let group = document.getElementById("board-actions");
  const aside = document.querySelector("aside.card") || document.querySelector("aside");
  if (!button) {
    if (!aside) return;
    group = document.createElement("div");
    group.className = "actions";
    group.id = "board-actions";
    button = document.createElement("button");
    button.id = "update";
    button.type = "button";
    button.className = "update";
    button.textContent = "Update";
    group.append(button);
    const status = document.getElementById("status");
    if (status) group.append(status);
    aside.appendChild(group);
  }
  button.onclick = refreshAll;
  // If an older layout left actions at the top, pin them under the boss list.
  if (aside && group && group.parentNode === aside) {
    const bosses = document.getElementById("bosses");
    if (bosses && group.previousElementSibling !== bosses) aside.appendChild(group);
  }
}
async function refreshWom() {
  const status = document.getElementById("status");
  try {
    for (const member of BOARD.members) {
      const response = await fetch("https://api.wiseoldman.net/v2/players/" + encodeURIComponent(member.rsn));
      if (!response.ok) continue;
      applySnapshot(member, await response.json());
    }
    if (!refreshing) status.textContent = "Saved hiscores loaded. Update checks them again.";
  } catch (e) {
    if (!refreshing) status.textContent = "Hiscores did not answer. Saved kill counts still work.";
  }
  if (!refreshing && !document.querySelector(".fill.arm")) renderMain();
}
async function refreshAll() {
  if (refreshing) return;
  refreshing = true;
  const button = document.getElementById("update");
  const status = document.getElementById("status");
  if (button) { button.disabled = true; button.textContent = "Checking…"; }
  let updated = 0;
  let failed = 0;
  for (const member of BOARD.members) {
    status.textContent = "Checking hiscores for " + member.rsn + "…";
    try {
      let response = await fetch("https://api.wiseoldman.net/v2/players/" + encodeURIComponent(member.rsn), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: "{}",
      });
      if (!response.ok) response = await fetch("https://api.wiseoldman.net/v2/players/" + encodeURIComponent(member.rsn));
      if (!response.ok) { failed++; continue; }
      applySnapshot(member, await response.json());
      updated++;
    } catch (e) {
      failed++;
    }
  }
  let clogNote = " Collection logs did not change.";
  status.textContent = "Checking collection logs…";
  try {
    const names = await refreshLogs();
    clogNote = names.length
      ? " Collection log updated for " + names.join(", ") + "."
      : " No RuneProfile collection log was ready.";
  } catch (e) {
    clogNote = " Collection logs did not answer.";
  }
  status.textContent = (failed
    ? "Checked " + updated + " hiscores. " + failed + " did not answer."
    : "Hiscores checked for all 5.") + clogNote;
  if (button) { button.disabled = false; button.textContent = "Update"; }
  refreshing = false;
  renderMain();
}


