function themeFor(slug) {
  if (ATM_THEMES[slug]) return ATM_THEMES[slug];
  // DT corners share the desert-treasure-ii integrated wash.
  if (typeof ATM_DT !== "undefined" && ATM_DT.indexOf(slug) !== -1) return ATM_THEMES["desert-treasure-ii"] || null;
  return null;
}
function themeTitleFile(slug) {
  const t = themeFor(slug);
  if (!t) return null;
  if (t.titleFile) return t.titleFile;
  // Convention: assets/themes/<slug>-title.webp (wired once the file is shipped / titleFile set in manifest).
  return null;
}
function themeWashFile(slug) {
  const t = themeFor(slug);
  if (t && t.washFile) return t.washFile;
  return null;
}
function isDtAtmosphere(slug) {
  return slug === "desert-treasure-ii" || ATM_DT.indexOf(slug) !== -1;
}
function isCgAtmosphere(slug) {
  return slug === "the-corrupted-gauntlet";
}
function isYamaAtmosphere(slug) {
  return slug === "yama";
}
function isZulrahAtmosphere(slug) {
  return slug === "zulrah";
}
function isGwdAtmosphere(slug) {
  return Object.prototype.hasOwnProperty.call(ATM_GWD, slug);
}
function hasAtmTitlePlate(slug) {
  // washFile with baked title OR floating titleFile both supply the heading
  return !!(themeTitleFile(slug) || themeWashFile(slug));
}
function hasAtmIntegratedWash(slug) {
  // Integrated Imagine scene+title — no separate floating title plate
  const t = themeFor(slug);
  return !!(t && t.washFile && !t.titleFile);
}
