function applyThemeAssets(slug) {
  const wash = document.getElementById("atm-theme-wash");
  const title = document.getElementById("atm-theme-title");
  const theme = themeFor(slug);
  const washFile = themeWashFile(slug);
  const titleFile = themeTitleFile(slug);
  const integrated = hasAtmIntegratedWash(slug);
  // CG uses dedicated atm-cg-wash; Zulrah/others use atm-theme-wash for integrated scenes.
  if (wash) {
    if (washFile && !isCgAtmosphere(slug)) {
      wash.alt = (theme && theme.title) || "";
      wash.src = depthPrefix() + "assets/themes/" + washFile;
      wash.classList.add("on");
      if (integrated) wash.classList.add("integrated");
      else wash.classList.remove("integrated");
    } else {
      wash.removeAttribute("src");
      wash.classList.remove("on");
      wash.classList.remove("integrated");
    }
  }
  if (title) {
    // Floating title plate only when titleFile is set (not wash-baked integrated scenes).
    if (titleFile && !integrated && !isCgAtmosphere(slug) && !isZulrahAtmosphere(slug)) {
      title.alt = (theme && theme.title) || "";
      title.src = depthPrefix() + "assets/themes/" + titleFile;
      title.classList.add("on");
    } else {
      title.removeAttribute("src");
      title.classList.remove("on");
    }
  }
  // Sync CG dedicated wash src from theme when present.
  const cgWash = document.getElementById("atm-cg-wash");
  if (cgWash && isCgAtmosphere(slug) && washFile) {
    cgWash.src = depthPrefix() + "assets/themes/" + washFile;
    cgWash.classList.add("integrated");
  }
  return !!(titleFile || washFile);
}
function updateAtmosphere() {
  ensureAtmosphere();
  const slug = slugFromHash();
  document.body.dataset.slug = slug;
  const hero = document.getElementById("atm-hero");
  const dt = document.getElementById("atm-dt");
  const gwd = document.getElementById("atm-gwd");
  const yama = document.getElementById("atm-yama");
  const zulrah = document.getElementById("atm-zulrah");
  if (!hero) return;
  if (yama) yama.classList.remove("on");
  if (zulrah) zulrah.classList.remove("on");
  if (gwd) gwd.classList.remove("on");
  applyThemeAssets(slug);
  if (isCgAtmosphere(slug)) {
    document.body.dataset.atm = "cg";
    document.body.dataset.theme = "the-corrupted-gauntlet";
    hero.removeAttribute("src");
    hero.style.opacity = "0";
    if (dt) dt.classList.remove("on");
    if (gwd) gwd.classList.remove("on");
    setAtmCredit("cg");
    return;
  }
  if (isDtAtmosphere(slug)) {
    document.body.dataset.atm = "dt";
    document.body.dataset.theme = slug;
    hero.removeAttribute("src");
    hero.style.opacity = "0";
    if (dt) dt.classList.add("on");
    if (gwd) gwd.classList.remove("on");
    setAtmCredit(hasAtmIntegratedWash(slug) || hasAtmIntegratedWash("desert-treasure-ii") ? "theme" : "default");
    return;
  }
  if (isZulrahAtmosphere(slug)) {
    document.body.dataset.atm = "zulrah";
    document.body.dataset.theme = "zulrah";
    if (dt) dt.classList.remove("on");
    if (gwd) gwd.classList.remove("on");
    if (zulrah) zulrah.classList.add("on");
    setAtmCredit("zulrah");
    // Integrated Zulrah scene already contains the boss and baked title; never stack hero art on it.
    if (hasAtmIntegratedWash(slug)) {
      hero.removeAttribute("src");
      hero.style.opacity = "0";
      return;
    }
    const next = depthPrefix() + "assets/bosses/zulrah-serpentine.webp";
    if (hero.getAttribute("src") === next) {
      hero.style.opacity = "";
      return;
    }
    hero.style.opacity = "0";
    const probe = new Image();
    probe.onload = function () {
      hero.dataset.slug = "zulrah";
      hero.style.setProperty("--atm-scale", String(ATM_SCALE.zulrah || 1));
      hero.src = next;
      hero.style.opacity = "";
    };
    probe.onerror = function () {
      const fallback = depthPrefix() + "assets/bosses/zulrah.webp";
      hero.dataset.slug = "zulrah";
      hero.style.setProperty("--atm-scale", String(ATM_SCALE.zulrah || 1));
      hero.src = fallback;
      hero.style.opacity = "";
    };
    probe.src = next;
    return;
  }
  if (isYamaAtmosphere(slug)) {
    document.body.dataset.atm = "yama";
    document.body.dataset.theme = "yama";
    if (dt) dt.classList.remove("on");
    if (gwd) gwd.classList.remove("on");
    if (yama) yama.classList.add("on");
    setAtmCredit("yama");
    // Integrated Yama scene already contains the boss and baked title; never stack hero art on it.
    if (hasAtmIntegratedWash(slug)) {
      hero.removeAttribute("src");
      hero.style.opacity = "0";
      return;
    }
    const next = depthPrefix() + "assets/bosses/yama.webp";
    if (hero.getAttribute("src") === next) {
      hero.style.opacity = "";
      return;
    }
    hero.style.opacity = "0";
    const probe = new Image();
    probe.onload = function () {
      hero.dataset.slug = "yama";
      hero.style.setProperty("--atm-scale", String(ATM_SCALE.yama || 1));
      hero.src = next;
      hero.style.opacity = "";
    };
    probe.onerror = function () {
      hero.removeAttribute("src");
      hero.style.opacity = "0";
    };
    probe.src = next;
    return;
  }
  if (isGwdAtmosphere(slug)) {
    document.body.dataset.atm = "gwd";
    document.body.dataset.theme = slug;
    if (dt) dt.classList.remove("on");
    if (yama) yama.classList.remove("on");
    if (zulrah) zulrah.classList.remove("on");
    if (gwd) {
      gwd.classList.add("on");
      const bossImg = gwd.querySelector(".atm-gwd-boss");
      const minions = ATM_GWD[slug] || [];
      const prefix = depthPrefix() + "assets/bosses/";
      if (bossImg) {
        bossImg.dataset.slug = slug;
        bossImg.src = prefix + slug + ".webp";
      }
      gwd.querySelectorAll(".atm-gwd-minion").forEach(function (img) {
        const slot = Number(img.dataset.slot);
        const mSlug = minions[slot];
        if (mSlug) {
          img.dataset.slug = mSlug;
          img.src = prefix + mSlug + ".webp";
        } else {
          img.removeAttribute("src");
          img.removeAttribute("data-slug");
        }
      });
    }
    hero.removeAttribute("src");
    hero.style.opacity = "0";
    setAtmCredit(hasAtmIntegratedWash(slug) ? "theme" : "default");
    return;
  }
  document.body.dataset.atm = hasAtmTitlePlate(slug) ? "theme" : "";
  document.body.dataset.theme = slug;
  if (dt) dt.classList.remove("on");
  if (gwd) gwd.classList.remove("on");
  setAtmCredit(hasAtmTitlePlate(slug) ? "theme" : "default");
  if (ATM_BOSSES.indexOf(slug) === -1) {
    hero.removeAttribute("src");
    hero.style.opacity = "0";
    return;
  }
  const next = depthPrefix() + "assets/bosses/" + slug + ".webp";
  if (hero.getAttribute("src") === next) {
    hero.style.opacity = "";
    return;
  }
  hero.style.opacity = "0";
  const probe = new Image();
  probe.onload = function () {
    hero.dataset.slug = slug;
    hero.style.setProperty("--atm-scale", String(ATM_SCALE[slug] || 1));
    hero.src = next;
    hero.style.opacity = "";
  };
  probe.onerror = function () {
    hero.removeAttribute("src");
    hero.style.opacity = "0";
  };
  probe.src = next;
}

window.addEventListener("pointerdown", function () { soundOn = true; });
window.addEventListener("hashchange", render);
window.addEventListener("popstate", render);
render();
refreshWom();
refreshLogs().then(function () {
  if (document.querySelector(".fill.arm")) return;
  if (!refreshing) renderMain();
});
